module.exports = /*#__PURE__*/JSON.parse('[{"bereich":{"de":"Prozesse","en":"Processes"},"fragen":{"de":["Welche Kernprozesse (z. B. Auftragsabwicklung, Einkauf, Produktion) möchten Sie im ERP-System abbilden?","Gibt es Mehrstufen-Workflows (z. B. Freigaben), die automatisch ausgeführt werden sollen?","Wie häufig ändern sich Ihre Abläufe, und benötigen wir eine leicht anpassbare Workflow-Engine?","Welche Prozess-Ereignisse (z. B. Statuswechsel, Fehlermeldungen) müssen protokolliert werden?","Wie sollen Ausnahmen oder manuelle Eingriffe in Standardprozesse gehandhabt werden?"],"en":["Which core processes (e.g., order processing, purchasing, production) do you want to map in the ERP system?","Are there multi-level workflows (e.g., approvals) that should be executed automatically?","How often do your processes change, and do you need an easily adaptable workflow engine?","Which process events (e.g., status changes, error messages) need to be logged?","How should exceptions or manual interventions in standard processes be handled?"]}},{"bereich":{"de":"Stammdaten","en":"Master Data"},"fragen":{"de":["Welche Entitäten (Kunden, Artikel, Lieferanten usw.) sind für Ihr Geschäft essentiell?","Welche Pflichtfelder (z. B. Artikelnummer, Kundennummer) müssen für jede Entität hinterlegt sein?","Wie möchten Sie Dublettenprüfung und Datenvalidierung beim Anlegen neuer Datensätze umsetzen?","Besteht eine vorhandene Datenquelle, aus der wir Stammdaten migrieren können?","Sollen Änderungen an Stammdaten versioniert oder in einem Änderungslog festgehalten werden?"],"en":["Which entities (customers, items, suppliers, etc.) are essential for your business?","Which mandatory fields (e.g., item number, customer number) must be stored for each entity?","How would you like to implement duplicate checking and data validation when creating new records?","Is there an existing data source from which we can migrate master data?","Should changes to master data be versioned or recorded in a change log?"]}},{"bereich":{"de":"Rollen","en":"Roles"},"fragen":{"de":["Welche Benutzergruppen (z. B. Vertrieb, Buchhaltung, Lager) benötigen unterschiedliche Zugriffsrechte?","Welche Aktionen (lesen, anlegen, löschen) sollen Sie pro Rolle steuern können?","Benötigt jede Rolle eine eigene Start- und Übersichtsansicht im UI?","Gibt es temporäre Rollen (z. B. Urlaubsvertretung), die wir einfach zuweisen und entfernen können?","Sollen Sie Berechtigungen auf einzelne Datensätze (z. B. eigene Kunden) beschränken?"],"en":["Which user groups (e.g., sales, accounting, warehouse) need different access rights?","Which actions (read, create, delete) should be controllable per role?","Does each role require its own start and overview view in the UI?","Are there temporary roles (e.g., vacation replacement) that we can easily assign and remove?","Should permissions be restricted to individual records (e.g., own customers)?"]}},{"bereich":{"de":"Integration","en":"Integration"},"fragen":{"de":["Mit welchen Systemen (ERP, CRM, Onlineshop, Buchhaltung) sollen Daten ausgetauscht werden?","Welche Datenformate (JSON, XML, CSV) und Protokolle (REST, SOAP) bevorzugen Sie für die Anbindung?","Müssen Daten in Echtzeit synchronisiert werden oder genügen zeitlich geplante Batch-Jobs?","Wer übernimmt die Wartung und Überwachung der Schnittstellen nach der Einführung?","Gibt es bestehende API-Dokumentationen oder Middleware-Lösungen, die wir nutzen können?"],"en":["Which systems (ERP, CRM, online shop, accounting) should data be exchanged with?","Which data formats (JSON, XML, CSV) and protocols (REST, SOAP) do you prefer for the connection?","Does data need to be synchronized in real-time or are scheduled batch jobs sufficient?","Who will be responsible for the maintenance and monitoring of the interfaces after implementation?","Are there existing API documentation or middleware solutions that we can use?"]}},{"bereich":{"de":"Security","en":"Security"},"fragen":{"de":["Welche Authentifizierungsverfahren (Passwort, SSO, MFA) möchten Sie einsetzen?","Welche Daten gelten als besonders schützenswert und benötigen zusätzliche Verschlüsselung?","Soll das System detaillierte Audit-Logs für sicherheitsrelevante Aktionen führen?","Brauchen Sie IP-Restriktionen oder Netzwerk-Firewalls für den Zugriff auf das ERP?","Wie lange sollen Protokolldaten (Logs, Änderungen) aufbewahrt werden?"],"en":["Which authentication methods (password, SSO, MFA) would you like to use?","Which data is considered particularly sensitive and requires additional encryption?","Should the system maintain detailed audit logs for security-relevant actions?","Do you need IP restrictions or network firewalls for access to the ERP?","How long should log data (logs, changes) be retained?"]}},{"bereich":{"de":"Scalability","en":"Scalability"},"fragen":{"de":["Mit welchem jährlichen Datenwachstum rechnen Sie (Transaktionen, Dokumente)?","Wie viele gleichzeitige Benutzer werden maximal erwartet?","Planen Sie neben dem Hauptstandort weitere Mandanten oder Niederlassungen?","Möchten Sie das System in der Cloud, on-premise oder hybrid betreiben?","Sollen Module einzeln skaliert werden können (z. B. Separate Services für Reporting)?"],"en":["What annual data growth do you expect (transactions, documents)?","How many concurrent users are expected at most?","Are you planning additional clients or branches besides the main location?","Would you like to operate the system in the cloud, on-premise, or in a hybrid model?","Should modules be scalable individually (e.g., separate services for reporting)?"]}},{"bereich":{"de":"Analytics","en":"Analytics"},"fragen":{"de":["Welche Kennzahlen (Umsatz, Lagerbestand, Durchlaufzeit) müssen jederzeit abrufbar sein?","Benötigen Sie interaktive Dashboards oder regelmäßige automatisierte Reports?","Welche Filter- und Drill-Down-Funktionen sind für Ihre Auswertungen wichtig?","Sollen Daten aus Fremdsystemen (z. B. Webshop, CRM) in die Analysen einfließen?","Möchten Sie historische Trends über längere Zeiträume speichern und auswerten?"],"en":["Which key figures (sales, inventory, throughput time) must be available at all times?","Do you need interactive dashboards or regular automated reports?","Which filter and drill-down functions are important for your evaluations?","Should data from external systems (e.g., webshop, CRM) be included in the analyses?","Would you like to store and evaluate historical trends over longer periods?"]}},{"bereich":{"de":"Usability","en":"Usability"},"fragen":{"de":["Welche Endgeräte (Desktop, Tablet, Smartphone) sollen primär unterstützt werden?","Muss das Interface mehrsprachig umgesetzt werden?","Welche Schulungsaufwände pro Rolle sind akzeptabel (z. B. Selbstlernvideos, Workshops)?","Brauchen Sie konfigurierbare Dashboards oder Widgets für unterschiedliche Nutzer?","Wünschen Sie integrierte Hilfe- und Feedbackfunktionen direkt im System?"],"en":["Which end devices (desktop, tablet, smartphone) should be primarily supported?","Does the interface need to be implemented in multiple languages?","What level of training effort per role is acceptable (e.g., self-learning videos, workshops)?","Do you need configurable dashboards or widgets for different users?","Would you like integrated help and feedback functions directly in the system?"]}},{"bereich":{"de":"Support","en":"Support"},"fragen":{"de":["Wie schnell soll auf Fehler oder Anfragen (SLA-Zeitfenster) reagiert werden?","Welche Supportkanäle (E-Mail, Chat, Telefon) sollen verfügbar sein?","Möchten Sie ein integriertes Ticketsystem oder externe Tools anbinden?","Brauchen Sie Self-Service-Funktionen wie FAQs oder Troubleshooting-Guides?","Wie oft sollen Systemupdates durchgeführt und dokumentiert werden?"],"en":["How quickly should errors or requests be responded to (SLA time frames)?","Which support channels (email, chat, phone) should be available?","Would you like an integrated ticket system or to connect external tools?","Do you need self-service features like FAQs or troubleshooting guides?","How often should system updates be carried out and documented?"]}}]');

